function pobierzUzytkownika(id) {
  try {
    if (!id) throw new ValidationError("ID jest wymagane");
    if (id > 1000) throw new NotFoundError("Uzytkownik nie istnieje");
    return { id, imie: "Ala" };
  } catch (error) {
