class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = "ValidationError";
  }
}

class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = "NotFoundError";
  }
}

function pobierzUzytkownika(id) {
  try {
    if (!id) throw new ValidationError("ID jest wymagane");
    if (id > 1000) throw new NotFoundError("Uzytkownik nie istnieje");
    return { id, imie: "Ala" };
  } catch (error) {
    if (error instanceof ValidationError) {
      console.log(`Blad danych: ${error.message}`);
    } else if (error instanceof NotFoundError) {
      console.log(`Nie znaleziono: ${error.message}`);
    } else {
      console.log(`Nieoczekiwany blad: ${error.message}`);
    }
  }
}

