class BladWalidacji extends Error {
  constructor(message) {
    super(message);
    this.name = "BladWalidacji";
  }
}

const blad = new BladWalidacji("Nieprawidlowe dane");
console.log(blad.name); // "BladWalidacji"
console.log(blad.message); // "Nieprawidlowe dane"
console.log(blad instanceof Error); // true

class BladNieZnaleziono extends Error {
  constructor(message) {
    super(message);
    this.name = "BladNieZnaleziono";
  }
}

function znajdzProdukt(id, produkty) {
  if (!id) throw new BladWalidacji("ID jest wymagane");
  const produkt = produkty.find((p) => p.id === id);
  if (!produkt) throw new BladNieZnaleziono(`Produkt o id ${id} nie istnieje`);
  return produkt;
}

const produkty = [{ id: 1, nazwa: "Laptop" }];

try {
  znajdzProdukt(999, produkty);
} catch (error) {
  if (error instanceof BladWalidacji) {
    console.log(`Blad danych wejsciowych: ${error.message}`);
  } else if (error instanceof BladNieZnaleziono) {
    console.log(`Nie znaleziono: ${error.message}`);
  } else {
    console.log(`Nieoczekiwany blad: ${error.message}`);
  }
}
// "Nie znaleziono: Produkt o id 999 nie istnieje"

